using System;
using System.Collections.Generic;
using System.Linq;
class SkillChecks {
 static void Check(bool v,string text){if(!v)throw new Exception(text);}
 static PlayerClasses Classes(int initial,params int[] pairs){var c=new PlayerClasses();var inputs=Enumerable.Repeat("0",12).ToArray();for(int i=0;i<pairs.Length;i+=2)inputs[pairs[i]]=pairs[i+1].ToString();Check(c.TryApply(inputs,initial),"class fixture");return c;}
 static void Main(){
 Check(SkillCheckRules.Modifier(9,0,2,false,false)==-1,"negative modifier floor");Check(SkillCheckRules.Modifier(10,2,3,true,false)==6,"expertise");Check(SkillCheckRules.Modifier(10,0,3,true,true)==1&&SkillCheckRules.Modifier(10,0,3,false,true)==0,"jack of all trades skills only");Check(SkillCheckRules.SelectDie(3,19,true,false)==19&&SkillCheckRules.SelectDie(3,19,false,true)==3&&SkillCheckRules.SelectDie(3,0,true,true)==3,"advantage cancellation");Check(SkillCheckRules.EffectiveDie(1,true,1)==10&&SkillCheckRules.EffectiveDie(1,true,0)==1,"reliable talent requires proficiency");Check(!SkillCheckRules.Success(20,0,30)&&SkillCheckRules.Success(1,20,10),"no automatic ability check success or failure");
 var c=Classes(0,0,1);var picks=new Dictionary<string,int>{{"bg-tool",35},{"class0-0",0},{"class0-1",12}};int[] tiers;string error;Check(!SkillCreationRules.TryBuild(c,14,picks,out tiers,out error),"optional class skill must avoid background duplicate");picks["class0-0"]=1;Check(SkillCreationRules.TryBuild(c,14,picks,out tiers,out error),error);Check(tiers[0]==1&&tiers[15]==1&&tiers[12]==1&&tiers[1]==1&&tiers[4]==0&&tiers[35]==1,"no arbitrary duplicate replacement");picks["class0-1"]=1;Check(!SkillCreationRules.TryBuild(c,14,picks,out tiers,out error),"same-source duplication is invalid");
 var fixedDuplicate=Classes(7,7,1);var fixedPicks=new Dictionary<string,int>{{"class7-0",0},{"class7-1",1},{"class7-2",6},{"class7-3",12},{"expert0",0},{"expert1",1}};Check(SkillCreationRules.TryBuild(fixedDuplicate,3,fixedPicks,out tiers,out error),error);Check(tiers.Count(x=>x>0)==7&&tiers[54]==1,"fixed duplicate thieves tools grants nothing extra");List<SkillGrant> replacements;SkillCreationRules.Preview(fixedDuplicate,3,fixedPicks,out replacements,out error);Check(replacements.Count==0,"no replacement grants");
 picks=new Dictionary<string,int>{{"bg-tool",35},{"class0-0",0},{"class0-1",12},{"origin-0",21},{"origin-1",4},{"origin-2",6}};Check(SkillCreationRules.TryBuild(c,10,picks,out tiers,out error),error);Check(tiers[21]==1&&tiers[4]==1&&tiers[6]==1,"skilled feat mixed tools and skills");
 picks=new Dictionary<string,int>{{"bg-tool",18},{"class0-0",0},{"class0-1",12},{"origin-0",21},{"origin-1",27},{"origin-2",28}};Check(SkillCreationRules.TryBuild(c,1,picks,out tiers,out error),error);picks["origin-2"]=18;Check(!SkillCreationRules.TryBuild(c,1,picks,out tiers,out error),"crafter limited to fast crafting tools");
 var rogue=Classes(7,7,1);picks=new Dictionary<string,int>{{"bg-tool",35},{"class7-0",1},{"class7-1",2},{"class7-2",3},{"class7-3",6},{"expert0",2},{"expert1",3}};Check(SkillCreationRules.TryBuild(rogue,14,picks,out tiers,out error),error);Check(tiers[2]==2&&tiers[3]==2&&tiers[54]==1,"rogue expertise and thieves tools");picks["expert1"]=2;Check(!SkillCreationRules.TryBuild(rogue,14,picks,out tiers,out error),"expertise cannot stack");
 var multi=Classes(0,0,1,7,1,2,1,5,1,11,1);var slots=SkillCreationRules.BaseGrants(multi,14);Check(slots.Count(x=>x.Id.StartsWith("class7-"))==1&&slots.Count(x=>x.Id.StartsWith("class2-"))==1&&slots.Count(x=>x.Id.StartsWith("class5-"))==1,"multiclass skill grants");Check(slots.Any(x=>x.Id=="rogue-tool")&&!slots.Any(x=>x.Id=="druid-tool")&&slots.Count(x=>x.Id.StartsWith("bard-tool"))==1,"multiclass tool grants");
 var wizard=Classes(1,1,2);var preview=new int[55];preview[4]=preview[5]=1;Check(SkillCreationRules.ExpertiseGrants(wizard,preview).Single().Options.All(x=>x==4||x==5),"scholar restricted to eligible proficient skills");Check(SkillSourceTables.BackgroundNames.Length==16&&SkillSourceTables.ToolNames.Length==37&&SkillSourceTables.ClassOptions.Length==12,"source table counts");var fighter=new FighterFeatures();Check(!fighter.TacticalMind(1,8,10,2)&&fighter.SecondWindUsed==0,"tactical mind level gate");Check(!fighter.TacticalMind(2,1,20,10)&&fighter.SecondWindUsed==0,"failed tactical mind is free");Check(fighter.TacticalMind(2,8,10,2)&&fighter.SecondWindUsed==1,"successful tactical mind spends wind");Console.WriteLine("PASS: modifiers, expertise, background feats, duplicates, multiclass, scholar, advantage, reliable talent and DC rules");}
}
